// protects: structured PII (IDs, phones, emails, cards, IBAN, bank accounts) is found with exact
//   boundaries, and look-alike numbers that fail their checksum/context rule are not.
// fails_when: a pattern or validator regresses (wrong checksum weights, missing full-width
//   folding, card/phone patterns swallowing neighbours, account rule ignoring context).
// no_claim: real-world recall; these are hand-picked format cases, not a sample of user text.
//   Valid TW IDs were generated by an independent script, not by isValidTwId.
import { describe, expect, it } from 'vitest';
import { detectRegex, isValidIban, isValidTwId, luhn } from './regex';
import type { EntityType } from './types';

type Case = [input: string, type: EntityType | null, text?: string];

const CASES: Case[] = [
  ['A123456789', 'ID_NUMBER'],
  ['F234567898', 'ID_NUMBER'],
  ['z111222336', 'ID_NUMBER'],
  ['A812345671', 'ID_NUMBER'], // resident certificate, 2021 format
  ['AC12345679', 'ID_NUMBER'], // resident certificate, old format
  ['Ａ１２３４５６７８９', 'ID_NUMBER'], // full-width
  ['0912-345-678', 'PHONE'],
  ['0912345678', 'PHONE'],
  ['+886 912 345 678', 'PHONE'],
  ['(02)2345-6789', 'PHONE'],
  ['07-123-4567', 'PHONE'],
  ['+1 415 555 2671', 'PHONE'],
  ['wang.da-ming@example.com.tw', 'EMAIL'],
  ['4111 1111 1111 1111', 'CARD'],
  ['5555-5555-5555-4444', 'CARD'],
  ['378282246310005', 'CARD'],
  ['GB82 WEST 1234 5698 7654 32', 'ACCOUNT'],
  ['DE89370400440532013000', 'ACCOUNT'],
  ['帳號：012-34-567890-1', 'ACCOUNT', '012-34-567890-1'],
  ['account no. 1234567890123', 'ACCOUNT', '1234567890123'],
  ['A123456788', null], // checksum off by one
  ['A323456789', null], // second digit must be 1/2/8/9
  ['AE12345678', null], // old certificate second letter must be A-D
  ['4111 1111 1111 1112', null], // Luhn fails
  ['GB82 WEST 1234 5698 7654 31', null], // IBAN mod-97 fails
  ['1234567890123', null], // account-length number without account context
  ['order 0912345', null], // too short for a mobile number
  ['Annual report 2026-11-15', null],
  ['user@localhost', null],
  ['+12 34', null],
];

describe('regex recognizers: 30 format cases', () => {
  it.each(CASES)('%s -> %s', (input, type, text) => {
    const spans = detectRegex(input);
    if (type === null) {
      expect(spans).toEqual([]);
    } else {
      expect(spans).toHaveLength(1);
      expect(spans[0].type).toBe(type);
      expect(spans[0].text).toBe(text ?? input);
    }
  });
});

// protects: dates of birth (西元, 民國, Chinese numerals, English) are masked only with a birth
//   word nearby, and Taiwan street addresses are captured whole, starting at the city.
// fails_when: ordinary dates get masked as DOB, the address match starts mid-sentence
//   ("寄到台北市..."), or it stops short of the floor number.
// no_claim: addresses without a county/city name (left to GLiNER/Nano by design).
const EXTRA: Case[] = [
  ['生日：民國七十三年三月十二日', 'DATE_OF_BIRTH', '民國七十三年三月十二日'],
  ['他是 1984-03-12 出生的', 'DATE_OF_BIRTH', '1984-03-12'],
  ['出生日期 73年3月12日', 'DATE_OF_BIRTH', '73年3月12日'],
  ['Patient born March 12, 1984 in Leeds', 'DATE_OF_BIRTH', 'March 12, 1984'],
  ['DOB: 12/03/1984', 'DATE_OF_BIRTH', '12/03/1984'],
  ['病人林美玲，民國七十三年三月十二日生，診斷為糖尿病', 'DATE_OF_BIRTH', '民國七十三年三月十二日'],
  ['2026年11月15日生效', null], // 生效 is not a birth
  ['會議改到 2026-11-15 下午', null],
  ['Deadline is March 12, 2027', null],
  ['請寄到台北市大安區和平東路一段 999 號 8 樓，謝謝', 'ADDRESS', '台北市大安區和平東路一段 999 號 8 樓'],
  ['地址 106臺北市大安區新生南路三段12巷3弄5號', 'ADDRESS', '106臺北市大安區新生南路三段12巷3弄5號'],
  ['高雄市苓雅區四維三路2號', 'ADDRESS', '高雄市苓雅區四維三路2號'],
  ['台北市今天很熱', null],
  ['住在和平東路 999 號', null], // no city: model layers' job
];

describe('date of birth and Taiwan address', () => {
  it.each(EXTRA)('%s -> %s', (input, type, text) => {
    const spans = detectRegex(input);
    if (type === null) {
      expect(spans).toEqual([]);
    } else {
      expect(spans).toHaveLength(1);
      expect(spans[0].type).toBe(type);
      expect(spans[0].text).toBe(text ?? input);
    }
  });
});

describe('validators', () => {
  it('TW ID checksum', () => {
    expect(isValidTwId('A123456789')).toBe(true);
    expect(isValidTwId('A123456780')).toBe(false);
  });
  it('Luhn and IBAN', () => {
    expect(luhn('4111111111111111')).toBe(true);
    expect(luhn('4111111111111112')).toBe(false);
    expect(isValidIban('GB82WEST12345698765432')).toBe(true);
    expect(isValidIban('GB82WEST1234569876543')).toBe(false);
  });
});

describe('in running text', () => {
  it('finds several items with offsets into the original string', () => {
    const t = '請聯絡王先生 0912-345-678 或 wang@example.com，身分證 A123456789。';
    const spans = detectRegex(t);
    expect(spans.map((s) => s.type)).toEqual(['PHONE', 'EMAIL', 'ID_NUMBER']);
    for (const s of spans) expect(t.slice(s.start, s.end)).toBe(s.text);
  });
  it('full-width digits map back to the full-width original', () => {
    const t = '電話：０９１２－３４５－６７８';
    const [s] = detectRegex(t);
    expect(s.text).toBe('０９１２－３４５－６７８');
  });
});
